B.UQ=A.a(s(["\u092c\u0948\u091f\u0930\u0940 \u0916\u0924\u094d\u092e \u0915\u094d\u092f\u094b\u0902 \u0939\u094b \u091c\u093e\u0924\u0940 \u0939\u0948?","9V \u0914\u0930 1.5V \u092e\u0947\u0902 \u0915\u094d\u092f\u093e \u0905\u0902\u0924\u0930 \u0939\u0948?",u.Z,"\u092c\u0948\u091f\u0930\u0940 \u090f\u0938\u0940 \u0926\u0947\u0924\u0940 \u0939\u0948 \u092f\u093e \u0921\u0940\u0938\u0940?"]),t.s)
B.a25={"\u092c\u0948\u091f\u0930\u0940 \u0916\u0924\u094d\u092e \u0915\u094d\u092f\u094b\u0902 \u0939\u094b \u091c\u093e\u0924\u0940 \u0939\u0948?":0,"9V \u0914\u0930 1.5V \u092e\u0947\u0902 \u0915\u094d\u092f\u093e \u0905\u0902\u0924\u0930 \u0939\u0948?":1,[u.Z]:2,"\u092c\u0948\u091f\u0930\u0940 \u090f\u0938\u0940 \u0926\u0947\u0924\u0940 \u0939\u0948 \u092f\u093e \u0921\u0940\u0938\u0940?":3}
B.Zt=new A.y(B.a25,["\u092c\u0948\u091f\u0930\u0940 \u092e\u0947\u0902 \u0930\u0938\u093e\u092f\u0928 \u0938\u0940\u092e\u093f\u0924 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u0964 \u091c\u0948\u0938\u0947-\u091c\u0948\u0938\u0947 \u0915\u0930\u0902\u091f \u092c\u0939\u0924\u093e \u0939\u0948, \u0930\u0938\u093e\u092f\u0928 \u0938\u092e\u093e\u092a\u094d\u0924 \u0939\u094b \u091c\u093e\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0935\u094b\u0932\u094d\u091f\u0947\u091c 0 \u0939\u094b \u091c\u093e\u0924\u093e \u0939\u0948\u0964","\u0935\u094b\u0932\u094d\u091f\u0947\u091c \u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u0926\u092c\u093e\u0935 \u0939\u0948\u0964 9V \u092c\u0948\u091f\u0930\u0940 1.5V \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 6 \u0917\u0941\u0928\u093e \u091c\u094d\u092f\u093e\u0926\u093e \u091c\u094b\u0930 \u0938\u0947 \u0915\u0930\u0902\u091f \u0927\u0915\u0947\u0932\u0924\u0940 \u0939\u0948\u0964","\u092f\u0939 \u0936\u0949\u0930\u094d\u091f \u0938\u0930\u094d\u0915\u093f\u091f \u0939\u0948! \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0915\u0930\u0902\u091f \u092c\u0939\u0928\u0947 \u0938\u0947 \u0924\u093e\u0930 \u0917\u0930\u094d\u092e \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948 \u0914\u0930 \u0906\u0917 \u0932\u0917 \u0938\u0915\u0924\u0940 \u0939\u0948\u0964 \u0939\u092e\u0947\u0936\u093e \u0932\u094b\u0921 (\u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915) \u0932\u0917\u093e\u090f\u0902!","\u092c\u0948\u091f\u0930\u0940 \u0939\u092e\u0947\u0936\u093e \u0921\u093e\u092f\u0930\u0947\u0915\u094d\u091f \u0915\u0930\u0902\u091f (DC) \u0926\u0947\u0924\u0940 \u0939\u0948, \u091c\u094b \u090f\u0915 \u0939\u0940 \u0926\u093f\u0936\u093e \u092e\u0947\u0902 \u092c\u0939\u0924\u093e \u0939\u0948\u0964"],t.w)
B.Z4=new A.y(B.ae,["\u092c\u0948\u091f\u0930\u0940 (Battery - \u0921\u0940\u0938\u0940 \u092a\u093e\u0935\u0930 \u0938\u094d\u0930\u094b\u0924)","\u092c\u0948\u091f\u0930\u0940 \u0930\u093e\u0938\u093e\u092f\u0928\u093f\u0915 \u090a\u0930\u094d\u091c\u093e \u0938\u0947 \u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u0949\u0928\u094b\u0902 \u0915\u094b \u092a\u0930\u093f\u092a\u0925 \u092e\u0947\u0902 \u0915\u0948\u0938\u0947 \u0927\u0915\u094d\u0915\u093e \u0926\u0947\u0924\u0940 \u0939\u0948?","\u092c\u0948\u091f\u0930\u0940 \u090f\u0915 \u0935\u093f\u0926\u094d\u092f\u0941\u0924-\u0930\u093e\u0938\u093e\u092f\u0928\u093f\u0915 \u0938\u094d\u0930\u094b\u0924 \u0939\u0948 \u091c\u094b \u0930\u093e\u0938\u093e\u092f\u0928\u093f\u0915 \u090a\u0930\u094d\u091c\u093e \u0915\u094b \u0935\u094b\u0932\u094d\u091f\u0947\u091c (\u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u0926\u092c\u093e\u0935) \u092e\u0947\u0902 \u092c\u0926\u0932\u0924\u0940 \u0939\u0948\u0964 \u0907\u0938\u092e\u0947\u0902 \u0927\u0928\u093e\u0924\u094d\u092e\u0915 (+) \u0914\u0930 \u090b\u0923\u093e\u0924\u094d\u092e\u0915 (\u2212) \u0938\u093f\u0930\u0947 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902, \u091c\u094b \u0921\u0940\u0938\u0940 \u0915\u0930\u0902\u091f \u0915\u094b \u092a\u0930\u093f\u092a\u0925 \u092e\u0947\u0902 \u092a\u094d\u0930\u0935\u093e\u0939\u093f\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964","\u092f\u093e\u0926 \u0930\u0916\u0928\u0947 \u0915\u093e \u0909\u0926\u093e\u0939\u0930\u0923: \u091b\u0924 \u092a\u0930 \u0930\u0916\u0940 \u092a\u093e\u0928\u0940 \u0915\u0940 \u091f\u0902\u0915\u0940 \u0914\u0930 \u092a\u0902\u092a \u091c\u0948\u0938\u093e! \u092a\u0902\u092a \u092a\u093e\u0928\u0940 \u0915\u094b \u0926\u092c\u093e\u0935 (\u0935\u094b\u0932\u094d\u091f\u0947\u091c) \u0915\u0947 \u0938\u093e\u0925 \u0928\u0940\u091a\u0947 \u092a\u093e\u0907\u092a\u094b\u0902 \u092e\u0947\u0902 \u092d\u0947\u091c\u0924\u093e \u0939\u0948\u0964","\u0915\u093e\u0930\u0923 \u0914\u0930 \u092a\u094d\u0930\u092d\u093e\u0935: \u092c\u093f\u0928\u093e \u0935\u094b\u0932\u094d\u091f\u0947\u091c \u0915\u0947 \u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u0949\u0928 \u0938\u094d\u0925\u093f\u0930 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964 \u092c\u0948\u091f\u0930\u0940 \u0915\u093e \u0935\u094b\u0932\u094d\u091f\u0947\u091c \u0938\u0947\u0902\u0938\u0930 \u0914\u0930 \u092e\u094b\u091f\u0930 \u0915\u094b \u090a\u0930\u094d\u091c\u093e\u0935\u093e\u0928 \u092c\u0928\u093e\u0924\u093e \u0939\u0948\u0964","\u0905\u0938\u0932\u0940 \u0926\u0941\u0928\u093f\u092f\u093e \u092e\u0947\u0902: \u0938\u094d\u092e\u093e\u0930\u094d\u091f\u092b\u094b\u0928, \u0930\u094b\u092c\u094b\u091f \u0915\u093e\u0930, \u0921\u094d\u0930\u094b\u0928, \u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u093f\u0915 \u0917\u093e\u0921\u093c\u093f\u092f\u093e\u0901 \u0914\u0930 \u0930\u093f\u092e\u094b\u091f \u0915\u0902\u091f\u094d\u0930\u094b\u0932 \u092e\u0947\u0902\u0964","\u0915\u092c \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930\u0947\u0902: \u091c\u092c \u0930\u094b\u092c\u094b\u091f \u0915\u094b \u092c\u093f\u0928\u093e \u0924\u093e\u0930 \u0915\u0947 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930 \u0930\u0942\u092a \u0938\u0947 \u091a\u0932\u093e\u0928\u093e \u0939\u094b\u0964",B.Wc,B.UQ,B.Zt],t.R)
