B.Sh=A.a(s(["\u090f\u0932\u0908\u0921\u0940 \u0915\u0940 \u090f\u0915 \u091f\u093e\u0902\u0917 \u0932\u0902\u092c\u0940 \u0915\u094d\u092f\u094b\u0902 \u0939\u094b\u0924\u0940 \u0939\u0948?","\u090f\u0932\u0908\u0921\u0940 \u0915\u094b \u0909\u0932\u094d\u091f\u093e \u0932\u0917\u093e\u090f\u0902 \u0924\u094b \u0915\u094d\u092f\u093e \u0939\u094b\u0917\u093e?",u.r,"\u0915\u094b\u0921 \u0938\u0947 \u090f\u0932\u0908\u0921\u0940 \u0915\u0948\u0938\u0947 \u092c\u094d\u0932\u093f\u0902\u0915 \u0939\u094b\u0924\u0940 \u0939\u0948?"]),t.s)
B.a2w={"\u090f\u0932\u0908\u0921\u0940 \u0915\u0940 \u090f\u0915 \u091f\u093e\u0902\u0917 \u0932\u0902\u092c\u0940 \u0915\u094d\u092f\u094b\u0902 \u0939\u094b\u0924\u0940 \u0939\u0948?":0,"\u090f\u0932\u0908\u0921\u0940 \u0915\u094b \u0909\u0932\u094d\u091f\u093e \u0932\u0917\u093e\u090f\u0902 \u0924\u094b \u0915\u094d\u092f\u093e \u0939\u094b\u0917\u093e?":1,[u.r]:2,"\u0915\u094b\u0921 \u0938\u0947 \u090f\u0932\u0908\u0921\u0940 \u0915\u0948\u0938\u0947 \u092c\u094d\u0932\u093f\u0902\u0915 \u0939\u094b\u0924\u0940 \u0939\u0948?":3}
B.Yl=new A.y(B.a2w,["\u0932\u0902\u092c\u0940 \u091f\u093e\u0902\u0917 \u090f\u0928\u094b\u0921 (+) \u0939\u094b\u0924\u0940 \u0939\u0948 \u0924\u093e\u0915\u093f \u0906\u092a \u0906\u0938\u093e\u0928\u0940 \u0938\u0947 \u092a\u0939\u091a\u093e\u0928 \u0938\u0915\u0947\u0902 \u0915\u093f \u0915\u094c\u0928 \u0938\u093e \u0938\u093f\u0930\u093e \u092a\u094d\u0932\u0938 \u0939\u0948\u0964","5V \u092a\u0930 \u090f\u0932\u0908\u0921\u0940 \u0916\u0930\u093e\u092c \u0928\u0939\u0940\u0902 \u0939\u094b\u0917\u0940, \u0932\u0947\u0915\u093f\u0928 \u091c\u0932\u0947\u0917\u0940 \u092d\u0940 \u0928\u0939\u0940\u0902 \u0915\u094d\u092f\u094b\u0902\u0915\u093f \u092f\u0939 \u0909\u0932\u094d\u091f\u0947 \u0915\u0930\u0902\u091f \u0915\u094b \u0930\u094b\u0915 \u0926\u0947\u0924\u0940 \u0939\u0948\u0964","\u090f\u0932\u0908\u0921\u0940 \u0915\u093e \u0906\u0902\u0924\u0930\u093f\u0915 \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927 \u092c\u0939\u0941\u0924 \u0915\u092e \u0939\u094b\u0924\u093e \u0939\u0948\u0964 \u0938\u0940\u0927\u0947 5V \u0926\u0947\u0928\u0947 \u092a\u0930 85 mA \u0915\u0930\u0902\u091f \u0906\u0915\u0930 \u0938\u093f\u0932\u093f\u0915\u0949\u0928 \u0935\u093e\u092f\u0930 \u0915\u094b \u092a\u093f\u0918\u0932\u093e \u0926\u0947\u0924\u093e \u0939\u0948\u0964","Arduino \u092a\u093f\u0928 \u0915\u094b digitalWrite(HIGH) \u0914\u0930 LOW \u0915\u0947 \u092c\u0940\u091a delay(500) \u0938\u0947 \u092c\u0926\u0932\u0915\u0930!"],t.w)
B.Z_=new A.y(B.ae,["\u090f\u0932\u0908\u0921\u0940 (LED - \u092a\u094d\u0930\u0915\u093e\u0936 \u0909\u0924\u094d\u0938\u0930\u094d\u091c\u0915 \u0921\u093e\u092f\u094b\u0921)","\u090f\u0932\u0908\u0921\u0940 \u0915\u0947\u0935\u0932 \u090f\u0915 \u0939\u0940 \u0926\u093f\u0936\u093e \u092e\u0947\u0902 \u0915\u094d\u092f\u094b\u0902 \u091c\u0932\u0924\u0940 \u0939\u0948 \u0914\u0930 \u0907\u0938\u0947 \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0915\u094d\u092f\u094b\u0902 \u0939\u094b\u0924\u0940 \u0939\u0948?","\u090f\u0932\u0908\u0921\u0940 \u090f\u0915 \u0905\u0930\u094d\u0927\u091a\u093e\u0932\u0915 \u0918\u091f\u0915 \u0939\u0948 \u091c\u094b \u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u090a\u0930\u094d\u091c\u093e \u0915\u094b \u092a\u094d\u0930\u0915\u093e\u0936 \u092e\u0947\u0902 \u092c\u0926\u0932\u0924\u093e \u0939\u0948\u0964 \u092f\u0939 \u0915\u0947\u0935\u0932 \u090f\u0915 \u0926\u093f\u0936\u093e \u092e\u0947\u0902 \u0915\u093e\u092e \u0915\u0930\u0924\u0940 \u0939\u0948: \u0915\u0930\u0902\u091f \u0932\u0902\u092c\u0940 \u091f\u093e\u0902\u0917 \u090f\u0928\u094b\u0921 (+) \u0938\u0947 \u091b\u094b\u091f\u0940 \u091f\u093e\u0902\u0917 \u0915\u0948\u0925\u094b\u0921 (\u2212) \u0915\u0940 \u0913\u0930 \u092c\u0939\u0924\u093e \u0939\u0948\u0964","\u092f\u093e\u0926 \u0930\u0916\u0928\u0947 \u0915\u093e \u0909\u0926\u093e\u0939\u0930\u0923: \u0925\u0940\u092e \u092a\u093e\u0930\u094d\u0915 \u0915\u0947 \u090f\u0915\u0924\u0930\u092b\u093e \u0918\u0942\u092e\u0928\u0947 \u0935\u093e\u0932\u0947 \u0917\u0947\u091f \u091c\u0948\u0938\u093e! \u0932\u094b\u0917 (\u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u0949\u0928) \u0938\u093f\u0930\u094d\u092b \u090f\u0915 \u0939\u0940 \u0924\u0930\u092b \u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0939\u0930 \u092c\u093e\u0930 \u0917\u0947\u091f \u092a\u093e\u0930 \u0915\u0930\u0928\u0947 \u092a\u0930 \u090a\u092a\u0930 \u092c\u0932\u094d\u092c \u091a\u092e\u0915\u0924\u093e \u0939\u0948!","\u0915\u093e\u0930\u0923 \u0914\u0930 \u092a\u094d\u0930\u092d\u093e\u0935: \u092c\u093f\u0928\u093e 330 \u03a9 \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u0915\u0947 85 mA \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0915\u0930\u0902\u091f \u0918\u0941\u0938\u0915\u0930 \u090f\u0932\u0908\u0921\u0940 \u0915\u094b \u091c\u0932\u093e \u0926\u0947\u0924\u093e \u0939\u0948\u0964 \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u0915\u0930\u0902\u091f \u0915\u094b \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 9.1 mA \u092a\u0930 \u0930\u0916\u0924\u093e \u0939\u0948\u0964","\u0905\u0938\u0932\u0940 \u0926\u0941\u0928\u093f\u092f\u093e \u092e\u0947\u0902: \u091f\u094d\u0930\u0948\u092b\u093f\u0915 \u0932\u093e\u0907\u091f, \u092b\u094b\u0928 \u092b\u094d\u0932\u0948\u0936\u0932\u093e\u0907\u091f, \u0917\u093e\u0921\u093c\u093f\u092f\u094b\u0902 \u0915\u0940 \u092c\u094d\u0930\u0947\u0915 \u0932\u093e\u0907\u091f, \u091f\u0940\u0935\u0940 \u0930\u093f\u092e\u094b\u091f \u0914\u0930 \u0930\u094b\u092c\u094b\u091f \u0915\u0940 \u0906\u0902\u0916\u0947\u0902\u0964","\u0915\u092c \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930\u0947\u0902: \u091c\u092c \u0930\u094b\u092c\u094b\u091f \u0915\u094b \u091a\u093e\u0932\u0942/\u092c\u0902\u0926, \u0938\u093f\u0917\u094d\u0928\u0932 \u092f\u093e \u0916\u0924\u0930\u0947 \u0915\u093e \u0938\u0902\u0915\u0947\u0924 \u0926\u093f\u0916\u093e\u0928\u093e \u0939\u094b\u0964",B.TK,B.Sh,B.Yl],t.R)
