B.Zo=new A.y(B.a2b,["\u092a\u0939\u0932\u093e \u092c\u0948\u0902\u0921 \u092a\u0939\u0932\u093e \u0905\u0902\u0915, \u0926\u0942\u0938\u0930\u093e \u092c\u0948\u0902\u0921 \u0926\u0942\u0938\u0930\u093e \u0905\u0902\u0915, \u0924\u0940\u0938\u0930\u093e \u092c\u0948\u0902\u0921 \u0917\u0941\u0923\u0915 (10^N), \u0914\u0930 \u091a\u094c\u0925\u093e \u0938\u0939\u0928\u0936\u0940\u0932\u0924\u093e (\u0917\u094b\u0932\u094d\u0921 = \xb15%)\u0964 \u0909\u0926\u093e\u0939\u0930\u0923: \u092d\u0942\u0930\u093e (1), \u0915\u093e\u0932\u093e (0), \u0932\u093e\u0932 (x100) = 1,000 \u03a9!","\u0935\u094b\u0932\u094d\u091f\u0947\u091c = \u0915\u0930\u0902\u091f \xd7 \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0964 5V \u092a\u0930 \u092f\u0926\u093f \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927 \u092c\u0922\u093c\u093e\u090f\u0902\u0917\u0947 \u0924\u094b \u0915\u0930\u0902\u091f \u0916\u0941\u0926 \u092c \u0916\u0941\u0926 \u0915\u092e \u0939\u094b \u091c\u093e\u090f\u0917\u093e\u0964","\u0907\u0932\u0947\u0915\u094d\u091f\u094d\u0930\u0949\u0928\u094b\u0902 \u0915\u0947 \u0918\u0930\u094d\u0937\u0923 \u0938\u0947 \u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u090a\u0930\u094d\u091c\u093e \u090a\u0937\u094d\u092e\u093e (Heat) \u092e\u0947\u0902 \u092c\u0926\u0932 \u091c\u093e\u0924\u0940 \u0939\u0948\u0964 (P = I\xb2R).","\u0915\u0930\u0902\u091f \u0907\u0924\u0928\u093e \u0915\u092e \u0939\u094b \u091c\u093e\u090f\u0917\u093e \u0915\u093f \u090f\u0932\u0908\u0921\u0940 \u092c\u0939\u0941\u0924 \u0927\u0940\u092e\u0940 \u091c\u0932\u0947\u0917\u0940 \u092f\u093e \u091c\u0932\u0947\u0917\u0940 \u0939\u0940 \u0928\u0939\u0940\u0902\u0964"],t.w)
B.Zk=new A.y(B.ae,["\u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 (Resistor - \u0915\u0930\u0902\u091f \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0915)","\u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u0915\u0930\u0902\u091f \u0915\u094b \u0915\u0948\u0938\u0947 \u0927\u0940\u092e\u093e \u0915\u0930\u0924\u093e \u0939\u0948 \u0914\u0930 \u0930\u0902\u0917\u0940\u0928 \u092a\u091f\u094d\u091f\u093f\u092f\u093e\u0901 (Color Bands) \u0913\u092e (\u03a9) \u092e\u093e\u0928 \u0915\u0948\u0938\u0947 \u092c\u0924\u093e\u0924\u0940 \u0939\u0948\u0902?","\u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u090f\u0915 \u0918\u091f\u0915 \u0939\u0948 \u091c\u094b \u0913\u092e \u0915\u0947 \u0928\u093f\u092f\u092e (V = I \xd7 R) \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0915\u0930\u0902\u091f \u0915\u0947 \u092a\u094d\u0930\u0935\u093e\u0939 \u0915\u094b \u0930\u094b\u0915\u0924\u093e \u0939\u0948\u0964 \u0907\u0938\u0947 \u0913\u092e (\u03a9) \u092e\u0947\u0902 \u092e\u093e\u092a\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 4 \u0930\u0902\u0917\u0940\u0928 \u092a\u091f\u094d\u091f\u093f\u092f\u093e\u0901 \u0907\u0938\u0915\u0947 \u092e\u093e\u0928 \u0914\u0930 \u0938\u0939\u0928\u0936\u0940\u0932\u0924\u093e (\u0917\u094b\u0932\u094d\u0921 = \xb15%) \u0915\u094b \u0926\u0930\u094d\u0936\u093e\u0924\u0940 \u0939\u0948\u0902\u0964","\u092f\u093e\u0926 \u0930\u0916\u0928\u0947 \u0915\u093e \u0909\u0926\u093e\u0939\u0930\u0923: \u092a\u093e\u0928\u0940 \u0915\u0947 \u092a\u093e\u0907\u092a \u092e\u0947\u0902 \u0938\u0902\u0915\u0930\u0940 \u091c\u0917\u0939 \u091c\u0948\u0938\u093e! \u091a\u094c\u0921\u093c\u0947 \u092a\u093e\u0907\u092a \u0938\u0947 \u092c\u0947\u0915\u093e\u092c\u0942 \u092a\u093e\u0928\u0940 \u092c\u0939\u0924\u093e \u0939\u0948, \u0932\u0947\u0915\u093f\u0928 \u092a\u093e\u0907\u092a \u0915\u094b \u0926\u092c\u093e\u0928\u0947 \u092a\u0930 \u092a\u093e\u0928\u0940 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0927\u093e\u0930 \u092e\u0947\u0902 \u092c\u0926\u0932 \u091c\u093e\u0924\u093e \u0939\u0948\u0964","\u0915\u093e\u0930\u0923 \u0914\u0930 \u092a\u094d\u0930\u092d\u093e\u0935: \u0928\u093e\u091c\u0941\u0915 \u092a\u093e\u0930\u094d\u091f\u094d\u0938 (\u091c\u0948\u0938\u0947 \u090f\u0932\u0908\u0921\u0940 \u0914\u0930 \u0938\u0947\u0902\u0938\u0930) \u0938\u0940\u0927\u093e \u0915\u0930\u0902\u091f \u0928\u0939\u0940\u0902 \u091d\u0947\u0932 \u0938\u0915\u0924\u0947\u0964 \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u090a\u0930\u094d\u091c\u093e \u0938\u094b\u0916\u0915\u0930 \u092a\u0941\u0930\u094d\u091c\u094b\u0902 \u0915\u094b \u091c\u0932\u0928\u0947 \u0938\u0947 \u092c\u091a\u093e\u0924\u093e \u0939\u0948\u0964","\u0905\u0938\u0932\u0940 \u0926\u0941\u0928\u093f\u092f\u093e \u092e\u0947\u0902: \u092e\u094b\u092c\u093e\u0907\u0932 \u091a\u093e\u0930\u094d\u091c\u0930, \u0935\u0949\u0932\u094d\u092f\u0942\u092e \u0928\u0949\u092c, \u091f\u0940\u0935\u0940 \u0938\u0930\u094d\u0915\u093f\u091f \u092c\u094b\u0930\u094d\u0921 \u0914\u0930 \u0939\u0940\u091f\u0930 \u092e\u0947\u0902\u0964","\u0915\u092c \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930\u0947\u0902: \u090f\u0932\u0908\u0921\u0940 \u0915\u0947 \u0938\u093e\u0925 \u0939\u092e\u0947\u0936\u093e 220\u03a9\u2013330\u03a9 \u0932\u0917\u093e\u090f\u0902, \u0914\u0930 \u092c\u091f\u0928 \u0915\u0947 \u0938\u093e\u0925 10k\u03a9 \u092a\u0941\u0932-\u0905\u092a \u092a\u094d\u0930\u0924\u093f\u0930\u094b\u0927\u0915 \u0932\u0917\u093e\u090f\u0902\u0964",B.Ts,B.UN,B.Zo],t.R)
